create or replace function barberium.effective_addon_price(p_professional_id uuid,p_base_service_id uuid,p_addon_service_id uuid) returns integer language sql stable security definer set search_path='public','barberium','pg_temp' as $$ select coalesce(ps.custom_price_cents,sa.addon_price_cents,ad.price_cents) from public.service_addons sa join public.services ad on ad.id=sa.addon_service_id left join public.professional_services ps on ps.professional_id=p_professional_id and ps.service_id=ad.id and ps.is_active where sa.base_service_id=p_base_service_id and sa.addon_service_id=p_addon_service_id and sa.is_active and ad.is_active $$;
create or replace function barberium.effective_addon_duration(p_professional_id uuid,p_base_service_id uuid,p_addon_service_id uuid) returns integer language sql stable security definer set search_path='public','barberium','pg_temp' as $$ select coalesce(ps.custom_duration_min,sa.addon_duration_min,ad.duration_min) from public.service_addons sa join public.services ad on ad.id=sa.addon_service_id left join public.professional_services ps on ps.professional_id=p_professional_id and ps.service_id=ad.id and ps.is_active where sa.base_service_id=p_base_service_id and sa.addon_service_id=p_addon_service_id and sa.is_active and ad.is_active $$;
create or replace function barberium.effective_business_hours(p_unit_id uuid,p_professional_id uuid,p_date date) returns table(open_time time,close_time time,is_closed boolean) language plpgsql stable security definer set search_path='public','barberium','pg_temp' as $$ begin return query select h.open_time,h.close_time,h.is_closed from public.special_business_hours h where h.unit_id=p_unit_id and h.professional_id=p_professional_id and h.special_date=p_date limit 1; if found then return; end if; return query select h.open_time,h.close_time,h.is_closed from public.special_business_hours h where h.unit_id=p_unit_id and h.professional_id is null and h.special_date=p_date limit 1; if found then return; end if; return query select h.open_time,h.close_time,h.is_closed from public.business_hours h where h.unit_id=p_unit_id and h.professional_id=p_professional_id and h.weekday=extract(dow from p_date)::int limit 1; if found then return; end if; return query select h.open_time,h.close_time,h.is_closed from public.business_hours h where h.unit_id=p_unit_id and h.professional_id is null and h.weekday=extract(dow from p_date)::int limit 1; end $$;
create or replace function barberium.appointment_snapshot_guard() returns trigger language plpgsql security definer set search_path='public','barberium','pg_temp' as $$ declare s public.services; d int; begin if tg_op='INSERT' or new.service_id is distinct from old.service_id or new.professional_id is distinct from old.professional_id then if not barberium.professional_service_allowed(new.professional_id,new.service_id) then raise exception 'PROFESSIONAL_NOT_LINKED'; end if; select * into s from public.services where id=new.service_id and is_active; if s.id is null then raise exception 'SERVICE_NOT_FOUND'; end if; d:=barberium.effective_service_duration(new.professional_id,new.service_id); new.service_name_snapshot:=s.name; new.service_duration_min_snapshot:=d; end if; return new; end $$;
drop trigger if exists trg_appointment_snapshot_guard on public.appointments; create trigger trg_appointment_snapshot_guard before insert or update of service_id,professional_id on public.appointments for each row execute function barberium.appointment_snapshot_guard();
create or replace function barberium.appointment_addon_guard() returns trigger language plpgsql security definer set search_path='public','barberium','pg_temp' as $$ declare a public.appointments; s public.services; ep int; ed int; begin select * into a from public.appointments where id=new.appointment_id; if a.id is null then raise exception 'APPOINTMENT_NOT_FOUND'; end if; if not barberium.professional_service_allowed(a.professional_id,new.service_id) then raise exception 'PROFESSIONAL_NOT_LINKED_TO_ADDON'; end if; select * into s from public.services where id=new.service_id and is_active; if s.id is null then raise exception 'INVALID_ADDON'; end if; ep:=barberium.effective_addon_price(a.professional_id,a.service_id,new.service_id); ed:=barberium.effective_addon_duration(a.professional_id,a.service_id,new.service_id); if ep is null or ed is null then raise exception 'INVALID_ADDON'; end if; new.name_snapshot:=s.name; new.price_cents:=ep; new.duration_min:=ed; return new; end $$;
drop trigger if exists trg_appointment_addon_guard on public.appointment_addons; create trigger trg_appointment_addon_guard before insert or update of appointment_id,service_id on public.appointment_addons for each row execute function barberium.appointment_addon_guard();

create or replace function public.barberium_get_available_slots(p_barbershop_slug text,p_unit_slug text,p_professional_id uuid,p_service_id uuid,p_addon_service_ids uuid[],p_date date) returns jsonb language plpgsql stable security definer set search_path='public','barberium' as $$
declare v_b public.barbershops; v_u public.units; v_s public.services; v_open time; v_close time; v_closed boolean; v_duration int; v_slot int; v_min_advance int; v_days_ahead int; v_must_finish boolean; v_cur timestamp; v_start timestamptz; v_end timestamptz; v_result jsonb:='[]'::jsonb;
begin select * into v_b from public.barbershops where slug=p_barbershop_slug and status='active'; if not found then raise exception 'BARBERSHOP_NOT_FOUND'; end if; select * into v_u from public.units where barbershop_id=v_b.id and slug=p_unit_slug and is_active; if not found then raise exception 'UNIT_NOT_FOUND'; end if; if not exists(select 1 from public.professionals where id=p_professional_id and unit_id=v_u.id and is_active) then raise exception 'PROFESSIONAL_NOT_FOUND'; end if; select * into v_s from public.services where id=p_service_id and unit_id=v_u.id and is_active and service_kind in ('service','combo') and coalesce((settings->>'draft')::boolean,false)=false; if not found then raise exception 'SERVICE_NOT_FOUND'; end if; if not barberium.professional_service_allowed(p_professional_id,p_service_id) then return '[]'::jsonb; end if; if exists(select 1 from unnest(coalesce(p_addon_service_ids,'{}'::uuid[])) x where not exists(select 1 from public.service_addons a where a.base_service_id=p_service_id and a.addon_service_id=x and a.is_active) or not barberium.professional_service_allowed(p_professional_id,x)) then raise exception 'INVALID_ADDON'; end if; v_duration:=barberium.effective_service_duration(p_professional_id,p_service_id)+coalesce((select sum(barberium.effective_addon_duration(p_professional_id,p_service_id,x)) from unnest(coalesce(p_addon_service_ids,'{}'::uuid[])) x),0); v_slot:=coalesce((v_u.settings->>'slot_minutes')::int,10); v_min_advance:=coalesce((v_u.settings->>'min_advance_minutes')::int,0); v_days_ahead:=coalesce((v_u.settings->>'days_ahead')::int,30); v_must_finish:=coalesce((v_u.settings->>'must_finish_by_close')::boolean,true); if p_date < (now() at time zone v_b.timezone)::date or p_date > ((now() at time zone v_b.timezone)::date + v_days_ahead) then return '[]'::jsonb; end if; select h.open_time,h.close_time,h.is_closed into v_open,v_close,v_closed from barberium.effective_business_hours(v_u.id,p_professional_id,p_date) h; if not found or v_closed then return '[]'::jsonb; end if; v_cur:=p_date::timestamp+v_open; while v_cur < p_date::timestamp+v_close loop v_start:=v_cur at time zone v_b.timezone; v_end:=(v_cur+make_interval(mins=>v_duration)) at time zone v_b.timezone; if (not v_must_finish or v_end<=((p_date::timestamp+v_close) at time zone v_b.timezone)) and v_start>=now()+make_interval(mins=>v_min_advance) and not exists(select 1 from public.appointments a where a.professional_id=p_professional_id and a.status='confirmed' and tstzrange(a.starts_at,a.ends_at,'[)')&&tstzrange(v_start,v_end,'[)')) and not barberium.has_block_conflict(v_u.id,p_professional_id,v_start,v_end,null,null) then v_result:=v_result||jsonb_build_array(to_char(v_cur,'HH24:MI')); end if; v_cur:=v_cur+make_interval(mins=>v_slot); end loop; return v_result; end $$;

create or replace function public.barberium_staff_available_slots(p_professional_id uuid,p_service_id uuid,p_addon_service_ids uuid[],p_date date,p_exclude_appointment_id uuid default null) returns jsonb language plpgsql stable security definer set search_path='public','barberium','auth','pg_temp' as $$
declare m record; prof public.professionals; svc public.services; b public.barbershops; u public.units; v_open time; v_close time; v_closed boolean; v_duration int; v_slot int; v_cur timestamp; v_start timestamptz; v_end timestamptz; result jsonb:='[]'::jsonb;
begin if auth.uid() is null then raise exception 'Não autenticado'; end if; select * into m from barberium.staff_membership(); if m.member_id is null then raise exception 'Usuário sem acesso à equipe'; end if; if m.role='barber' then p_professional_id:=m.professional_id; end if; select * into prof from public.professionals where id=p_professional_id and barbershop_id=m.barbershop_id and is_active; if not found then raise exception 'Profissional inválido'; end if; select * into svc from public.services where id=p_service_id and unit_id=prof.unit_id and is_active; if not found then raise exception 'Serviço inválido'; end if; if not barberium.professional_service_allowed(prof.id,svc.id) then return result; end if; select * into b from public.barbershops where id=m.barbershop_id; select * into u from public.units where id=prof.unit_id; if exists(select 1 from unnest(coalesce(p_addon_service_ids,'{}'::uuid[])) x where not exists(select 1 from public.service_addons a where a.base_service_id=p_service_id and a.addon_service_id=x and a.is_active) or not barberium.professional_service_allowed(prof.id,x)) then raise exception 'Adicional inválido'; end if; v_duration:=barberium.effective_service_duration(prof.id,svc.id)+coalesce((select sum(barberium.effective_addon_duration(prof.id,svc.id,x)) from unnest(coalesce(p_addon_service_ids,'{}'::uuid[])) x),0); v_slot:=coalesce((u.settings->>'slot_minutes')::int,10); select h.open_time,h.close_time,h.is_closed into v_open,v_close,v_closed from barberium.effective_business_hours(u.id,prof.id,p_date) h; if not found or v_closed then return result; end if; v_cur:=p_date::timestamp+v_open; while v_cur<p_date::timestamp+v_close loop v_start:=v_cur at time zone coalesce(b.timezone,'America/Sao_Paulo'); v_end:=v_start+make_interval(mins=>v_duration); if v_end<=((p_date::timestamp+v_close) at time zone coalesce(b.timezone,'America/Sao_Paulo')) and (v_start>=now() or p_exclude_appointment_id is not null) and not exists(select 1 from public.appointments a where a.professional_id=prof.id and a.status='confirmed' and (p_exclude_appointment_id is null or a.id<>p_exclude_appointment_id) and tstzrange(a.starts_at,a.ends_at,'[)')&&tstzrange(v_start,v_end,'[)')) and not barberium.has_block_conflict(u.id,prof.id,v_start,v_end,null,null) then result:=result||jsonb_build_array(to_char(v_cur,'HH24:MI')); end if; v_cur:=v_cur+make_interval(mins=>v_slot); end loop; return result; end $$;

